    case 34:
      ACCEPT_TOKEN(anon_sym_impl);
      END_STATE();
    case 35:
      ACCEPT_TOKEN(anon_sym_self);
      END_STATE();
    case 36:
      ACCEPT_TOKEN(anon_sym_type);
      END_STATE();
    case 37:
      if (lookahead == 'e') ADVANCE(39);
      END_STATE();
    case 38:
